script.setup:
// opentype.js reads the font file and gives glyph outlines; particles settle onto them.
const mod = await ctx.utils.import("https://esm.sh/opentype.js@1.3.4");
const opentype = mod.default ?? mod;
const font = opentype.parse(await (await fetch(ctx.assets["Bungee-Regular.ttf"])).arrayBuffer());
const WORDS = ["SILJANGNIM", "OPEN SOURCE", "HELLO"];
const N = 5000;
// Outline → evenly spaced points, fitted to the canvas (uv, y up).
ctx.state.sample = (text) => {
  // Fit to the canvas as it is now: the size can change while the scene runs.
  const [w, h] = ctx.resolution;
  const segs = [];
  let cur = [0, 0], start = [0, 0];
  for (const c of font.getPath(text, 0, 0, 100).commands) {
    if (c.type === "M") { cur = [c.x, c.y]; start = cur; }
    else if (c.type === "L") { segs.push([cur, [c.x, c.y]]); cur = [c.x, c.y]; }
    else if (c.type === "Q" || c.type === "C") {
      for (let k = 1; k <= 10; k++) {
        const t = k / 10, m = 1 - t;
        const p = c.type === "Q"
          ? [m * m * cur[0] + 2 * m * t * c.x1 + t * t * c.x, m * m * cur[1] + 2 * m * t * c.y1 + t * t * c.y]
          : [m ** 3 * cur[0] + 3 * m * m * t * c.x1 + 3 * m * t * t * c.x2 + t ** 3 * c.x, m ** 3 * cur[1] + 3 * m * m * t * c.y1 + 3 * m * t * t * c.y2 + t ** 3 * c.y];
        segs.push([segs.length && k > 1 ? segs[segs.length - 1][1] : cur, p]);
      }
      cur = [c.x, c.y];
    } else if (c.type === "Z") { segs.push([cur, start]); cur = start; }
  }
  const lengths = segs.map(([a, b]) => Math.hypot(b[0] - a[0], b[1] - a[1]));
  const total = lengths.reduce((x, y) => x + y, 0);
  const pts = [];
  let si = 0, acc = 0;
  for (let i = 0; i < N; i++) {
    const d = (i / N) * total;
    while (si < segs.length - 1 && acc + lengths[si] < d) acc += lengths[si++];
    const [a, b] = segs[si], f = lengths[si] ? (d - acc) / lengths[si] : 0;
    pts.push(a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f);
  }
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (let i = 0; i < pts.length; i += 2) { x0 = Math.min(x0, pts[i]); x1 = Math.max(x1, pts[i]); y0 = Math.min(y0, pts[i + 1]); y1 = Math.max(y1, pts[i + 1]); }
  const aspect = w / h, scale = Math.min(0.84 * aspect / (x1 - x0), 0.5 / (y1 - y0));
  const out = new Float32Array(N * 2);
  for (let i = 0; i < N; i++) {
    out[i * 2] = 0.5 + ((pts[i * 2] - (x0 + x1) / 2) * scale) / aspect;
    out[i * 2 + 1] = 0.5 - (pts[i * 2 + 1] - (y0 + y1) / 2) * scale;
  }
  return out;
};
const pos = new Float32Array(N * 3);
for (let i = 0; i < N; i++) { pos[i * 3] = Math.random(); pos[i * 3 + 1] = Math.random(); pos[i * 3 + 2] = 0; }
const gl = ctx.gl, vao = gl.createVertexArray(), buffer = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 12, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 1, gl.FLOAT, false, 12, 8);
gl.bindVertexArray(null);
Object.assign(ctx.state, { WORDS, N, pos, vel: new Float32Array(N * 2), vao, buffer, word: -1, targets: null,
  p: ctx.utils.createProgram("#version 300 es\nlayout(location=0) in vec2 a_position; layout(location=1) in float a_t;\nuniform float u_size; out float v_t;\nvoid main(){ v_t = a_t; gl_Position = vec4(a_position * 2.0 - 1.0, 0.0, 1.0); gl_PointSize = u_size; }", "#version 300 es\nprecision highp float; in float v_t; out vec4 outColor; uniform vec3 u_left; uniform vec3 u_right;\nvoid main(){ float d = length(gl_PointCoord - 0.5); float a = smoothstep(0.5, 0.0, d);\n  outColor = vec4(mix(u_left, u_right, v_t) * a * 0.55, 1.0); }") });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const word = u.u_auto ? Math.floor(ctx.time / 5) % s.WORDS.length : u.u_word;
// A new size refits the word (portrait, landscape, full screen).
if (word !== s.word || ctx.resized) { s.word = word; s.targets = s.sample(s.WORDS[word]); }
const [mx, my] = [ctx.mouse[0], 1 - ctx.mouse[1]];
// The pointer starts at the center; it scatters particles only once it has moved.
s.moved ||= mx !== 0.5 || my !== 0.5;
for (let i = 0; i < s.N; i++) {
  const o = i * 3, v = i * 2;
  let x = s.pos[o], y = s.pos[o + 1];
  let vx = s.vel[v] + (s.targets[v] - x) * 0.02 * u.u_pull, vy = s.vel[v + 1] + (s.targets[v + 1] - y) * 0.02 * u.u_pull;
  const dx = x - mx, dy = y - my, d2 = dx * dx + dy * dy;
  if (s.moved && d2 < 0.01) { vx += dx * 0.004 / (d2 + 1e-4); vy += dy * 0.004 / (d2 + 1e-4); }
  vx = vx * 0.86 + (Math.random() - 0.5) * 0.0004; vy = vy * 0.86 + (Math.random() - 0.5) * 0.0004;
  s.vel[v] = vx; s.vel[v + 1] = vy;
  s.pos[o] = x + vx; s.pos[o + 1] = y + vy; s.pos[o + 2] = s.targets[v];
}
gl.clearColor(0.03, 0.03, 0.05, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
gl.useProgram(s.p);
ctx.utils.setUniforms(s.p, { u_size: 5 * Math.min(2, devicePixelRatio), u_left: u.u_left, u_right: u.u_right });
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, s.pos, gl.DYNAMIC_DRAW);
gl.drawArrays(gl.POINTS, 0, s.N);
gl.bindVertexArray(null); gl.disable(gl.BLEND);
